import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult
import kotlinx.coroutines.delay

// Retry the same call: the connection is fine, the service was briefly unavailable (Google's guidance for code 2).
suspend fun <T> retryOnUnavailable(maxTries: Int = 3, call: suspend () -> Pair<BillingResult, T>): Pair<BillingResult, T> {
    var delayMs = 2_000L
    var result = call()
    var tries = 1
    while (result.first.responseCode == BillingClient.BillingResponseCode.SERVICE_UNAVAILABLE && tries < maxTries) {
        delay(delayMs)
        delayMs *= 2 // exponential backoff, for work the person is not waiting on
        result = call()
        tries++
    }
    return result
}

import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult

// No automatic retry: tell the person, and let them try again after they fix the account or update the Play Store.
fun onPurchaseResult(result: BillingResult, showMessage: (String) -> Unit) {
    if (result.responseCode == BillingClient.BillingResponseCode.BILLING_UNAVAILABLE) {
        println("BILLING_UNAVAILABLE: ${result.debugMessage}")
        showMessage("Google Play cannot complete purchases right now. Check the Play Store and your payment method, then try again.")
    }
}

import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult

// ITEM_UNAVAILABLE is a catalog problem: log the product ID and hide the button instead of retrying.
fun onPurchaseResult(result: BillingResult, productId: String, hideProduct: (String) -> Unit) {
    if (result.responseCode == BillingClient.BillingResponseCode.ITEM_UNAVAILABLE) {
        println("ITEM_UNAVAILABLE for $productId: check it is active, the app is published and the country is allowed")
        hideProduct(productId)
    }
}

