import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult
import kotlinx.coroutines.delay

// Google: ERROR may be transient, so back off and retry a few times, then give up and report it.
suspend fun acknowledgeWithRetry(acknowledge: suspend () -> BillingResult): BillingResult {
    var wait = 2_000L
    var result = acknowledge()
    repeat(2) {
        if (result.responseCode != BillingClient.BillingResponseCode.ERROR) return result
        delay(wait)
        wait *= 2
        result = acknowledge()
    }
    return result
}

import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult
import com.android.billingclient.api.QueryPurchasesParams

// Treat ITEM_ALREADY_OWNED as good news: fetch what the user owns and grant it (Google's recommended fix).
fun onPurchaseResult(client: BillingClient, result: BillingResult) {
    if (result.responseCode == BillingClient.BillingResponseCode.ITEM_ALREADY_OWNED) {
        val params = QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.SUBS).build()
        client.queryPurchasesAsync(params) { queryResult, purchases ->
            if (queryResult.responseCode == BillingClient.BillingResponseCode.OK) {
                purchases.forEach { println("Already owned: ${it.products}") }
            }
        }
    }
}

import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult
import com.android.billingclient.api.QueryPurchasesParams

// After ITEM_NOT_OWNED, trust the fresh purchase list, not the purchase you held: it may already be consumed.
fun onAcknowledgeResult(client: BillingClient, result: BillingResult) {
    if (result.responseCode == BillingClient.BillingResponseCode.ITEM_NOT_OWNED) {
        val params = QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build()
        client.queryPurchasesAsync(params) { _, purchases ->
            println("The user currently owns ${purchases.size} one-time products")
        }
    }
}

import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult

// A dropped connection is retryable: ask the person to try again instead of showing a failure.
fun onBillingResult(result: BillingResult, showMessage: (String) -> Unit) {
    if (result.responseCode == BillingClient.BillingResponseCode.NETWORK_ERROR) {
        showMessage("Check your connection and try again.")
    }
}

import com.android.billingclient.api.BillingClient
import com.android.billingclient.api.BillingResult

// A cancel is the person's choice: no dialog, no retry. Log it at info level so real failures stay visible.
fun onPurchasesUpdated(result: BillingResult) {
    when (result.responseCode) {
        BillingClient.BillingResponseCode.USER_CANCELED -> println("Purchase cancelled by the user")
        BillingClient.BillingResponseCode.OK -> println("Purchase flow finished")
        else -> println("Billing result ${result.responseCode}: ${result.debugMessage}")
    }
}
